    (N'PIQUAGE-ILLICITE', N'PIQ-0002', N'Vol d''eau par un abonne (by-pass / mise en non conformite compteur) (prix/m3)', N'M3', N'PRESTATION', 40.95, NULL, NULL, N'PRESTATION', 0),
