) a(code_famille, code_article, libelle, unite, mode_prix, prix_unitaire, prix_fourniture, prix_pose, type_tva, avec_diametre)
INNER JOIN FamillesArticles f ON f.code_famille = a.code_famille
WHERE NOT EXISTS (SELECT 1 FROM ArticlesDevis ad WHERE ad.code_article = a.code_article);
GO

/* ------------------------------------------------------------
   3. TARIFS (periode ouverte a partir d'aujourd'hui)
   Insere un tarif uniquement pour les articles qui n'en ont pas
   deja un actuellement ouvert (date_fin IS NULL) - evite les doublons
   si ce script est relance ou execute apres le seed initial.
